        {[0, 0.2, 0.4, 0.6, 0.8, 1].map((v) => (
          <g key={v}>
            <line
              x1={x(v)}
              x2={x(v)}
              y1={top}
              y2={height - bottom}
              stroke="#f0f2f6"
            />
            <text
              x={x(v)}
              y={height - bottom + 23}
              textAnchor="middle"
              className="axis-text"
            >
              {v.toFixed(1)}
            </text>
          </g>
        ))}
        <g clipPath={`url(#${id})`}>
          {showTruth && (
            <path
              d={path("truth")}
              fill="none"
              stroke="#a9b0bc"
              strokeWidth="2"
              strokeDasharray="5 6"
            />
          )}
          {result?.validation.map((p, i) => (
            <circle
              key={`v${i}`}
              cx={x(p.x)}
              cy={y(p.y)}
              r="3"
              fill="#e6a08b"
              fillOpacity=".6"
            />
          ))}
          {result?.train.map((p, i) => (
            <circle
              key={i}
              cx={x(p.x)}
              cy={y(p.y)}
              r="4.6"
              fill="#359e94"
              fillOpacity=".86"
              stroke="white"
              strokeWidth="1.4"
            />
          ))}
          <path
            d={path("fit")}
            fill="none"
            stroke="#5163e5"
            strokeWidth="3"
            strokeLinecap="round"
          />
          {selected && (
            <>
              <line
                x1={x(selected.x)}
                x2={x(selected.x)}
                y1={top}
                y2={height - bottom}
                stroke="#5163e5"
                strokeDasharray="3 4"
              />
              <circle
                cx={x(selected.x)}
                cy={y(selected.fit)}
                r="5"
                fill="#5163e5"
                stroke="white"
                strokeWidth="2"
              />
            </>
          )}
        </g>
        <text
          x={width - right}
          y={height - 4}
          textAnchor="end"
          className="axis-label"
        >
          输入特征 x
        </text>
        <text x="15" y="17" className="axis-label">
          y
        </text>
        <rect
          x={left}
          y={top}
          width={plotWidth}
          height={plotHeight}
          fill="transparent"
          onMouseMove={(event) => {
            const bounds = event.currentTarget.getBoundingClientRect();
            setHover(
              Math.max(
                0,
                Math.min(
                  curve.length - 1,
                  Math.round(
                    ((event.clientX - bounds.left) / bounds.width) *
                      (curve.length - 1),
                  ),
                ),
              ),
            );
          }}
          onMouseLeave={() => setHover(null)}
        />
      </svg>
      {selected && (
        <div className="chart-tooltip">
          x {selected.x.toFixed(2)}
          <span>预测 {selected.fit.toFixed(3)}</span>
          <span>真实 {selected.truth.toFixed(3)}</span>
        </div>
      )}
      <div className="chart-legend">
        <span>
          <i className="dot teal" />
          训练样本
        </span>
        <span>
          <i className="dot coral" />
          验证样本
        </span>
        <span>
          <i className="line blue" />
          模型拟合
        </span>
        <button
          className={!showTruth ? "muted" : ""}
          onClick={() => setShowTruth(!showTruth)}
        >
          <i className="line dashed" />
          真实函数
        </button>
      </div>
      {clipped && (
        <p className="clipping-note">
          曲线超出当前纵轴范围，部分极值已裁切；误差仍由完整预测计算。
        </p>
      )}
    </div>
  );
}

export function ErrorChart({
  data,
  current,
}: {
  data: Sweep;
  current: number;
}) {
  const width = 600,
    height = 160,
    left = 45,
    top = 15,
    pw = 535,
    ph = 111;
  const values = data.points.flatMap((p) => [p.train_mse, p.validation_mse]);
  const low =
    Math.min(...values.map((v) => Math.log10(Math.max(v, 1e-7)))) - 0.15;
  const high =
    Math.max(...values.map((v) => Math.log10(Math.max(v, 1e-7)))) + 0.15;
  const x = (degree: number) => left + ((degree - 1) / 14) * pw;
  const y = (value: number) =>
    top + ((high - Math.log10(Math.max(value, 1e-7))) / (high - low)) * ph;
  const path = (key: "train_mse" | "validation_mse") =>
    data.points
      .map((p, i) => `${i ? "L" : "M"}${x(p.degree)},${y(p[key])}`)
      .join(" ");
  return (
    <svg
      className="error-chart"
      viewBox={`0 0 ${width} ${height}`}
      role="img"
      aria-label="不同模型阶数的训练与验证误差，纵轴为对数尺度"
    >
      {[0, 0.5, 1].map((f) => (
        <g key={f}>
          <line
            x1={left}
            x2={left + pw}
            y1={top + f * ph}
            y2={top + f * ph}
            stroke="#e9ecf2"
          />
          <text
            x={left - 9}
            y={top + f * ph + 4}
            textAnchor="end"
            className="axis-text"
          >
            {Math.pow(10, high - f * (high - low)).toPrecision(1)}
          </text>
        </g>
      ))}
      <line
        x1={x(current)}
        x2={x(current)}
        y1={top}
        y2={top + ph}
        stroke="#b9bfea"
        strokeDasharray="4 4"
      />
      <path
        d={path("train_mse")}
        stroke="#359e94"
        strokeWidth="2"
        fill="none"
      />
      <path
        d={path("validation_mse")}
        stroke="#e29a6b"
        strokeWidth="2.5"
        fill="none"
      />
      {data.points.map((p) => (
        <g key={p.degree}>
          <circle
            cx={x(p.degree)}
            cy={y(p.validation_mse)}
            r={p.degree === current ? 4 : 2.5}
            fill="#e29a6b"
          />
          <text
            x={x(p.degree)}
            y={height - 11}
            textAnchor="middle"
            className="axis-text"
          >
            {p.degree}
          </text>
        </g>
      ))}
    </svg>
  );
}
"use client";
import { useEffect, useRef, useState } from "react";
import type { BenchResult, Learning, Prediction } from "@/lib/bench";
import { number } from "@/lib/bench";

function useWidth() {
  const ref = useRef<HTMLDivElement>(null);
  const [width, setWidth] = useState(760);
  useEffect(() => {
    if (!ref.current) return;
    const observer = new ResizeObserver(([entry]) =>
      setWidth(Math.max(300, Math.round(entry.contentRect.width))),
    );
    observer.observe(ref.current);
    return () => observer.disconnect();
  }, []);
  return { ref, width };
}
function domain(values: number[]) {
  const minimum = Math.min(...values),
    maximum = Math.max(...values);
  const pad = Math.max((maximum - minimum) * 0.1, 0.01);
  return [minimum - pad, maximum + pad];
}
function tick(value: number) {
  return Math.abs(value) >= 1000
    ? value.toPrecision(3)
    : Number(value.toPrecision(3)).toString();
}

export function PredictionChart({
  result,
  mode,
  feature,
  showTraining,
}: {
  result: BenchResult;
  mode: "parity" | "residual" | "feature";
  feature: number;
  showTraining: boolean;
}) {
  const { ref, width } = useWidth();
  const height = width < 500 ? 285 : 340;
  const left = 55,
    right = 20,
    top = 20,
    bottom = 48;
  const [active, setActive] = useState<{
    point: Prediction;
    training: boolean;
  } | null>(null);
  useEffect(() => setActive(null), [result.fingerprint, mode, feature]);
  const points = [
    ...result.validation_predictions.map((point) => ({
      point,
      training: false,
    })),
    ...(showTraining
      ? result.training_predictions.map((point) => ({ point, training: true }))
      : []),
  ];
  const getX = (p: Prediction) =>
    mode === "parity"
      ? p.actual
      : mode === "residual"
        ? p.prediction
        : p.features[feature];
  const getY = (p: Prediction) =>
    mode === "residual"
      ? p.residual
      : mode === "feature"
        ? p.actual
        : p.prediction;
  let xd = domain(points.map((p) => getX(p.point))),
    yd = domain(points.map((p) => getY(p.point)));
  if (mode === "parity") {
    const limits = domain(
      points.flatMap((p) => [p.point.actual, p.point.prediction]),
    );
    xd = limits;
    yd = limits;
  }
  if (mode === "residual") {
    const max =
      Math.max(...points.map((p) => Math.abs(p.point.residual)), 0.1) * 1.15;
    yd = [-max, max];
  }
  const x = (value: number) =>
    left + ((value - xd[0]) / (xd[1] - xd[0])) * (width - left - right);
  const y = (value: number) =>
    top + ((yd[1] - value) / (yd[1] - yd[0])) * (height - top - bottom);
  const xLabel =
    mode === "parity"
      ? `真实值（${result.dataset.unit}）`
      : mode === "residual"
        ? `预测值（${result.dataset.unit}）`
        : result.dataset.features[feature];
  const yLabel =
    mode === "residual"
      ? "残差：真实−预测"
      : mode === "feature"
        ? result.dataset.target
        : "预测值";
  return (
    <div ref={ref} className="bench-chart">
      <svg
        viewBox={`0 0 ${width} ${height}`}
        role="img"
        aria-label={`${xLabel}与${yLabel}散点图`}
      >
        {[0, 0.25, 0.5, 0.75, 1].map((f) => {
          const xv = xd[0] + f * (xd[1] - xd[0]),
            yv = yd[0] + f * (yd[1] - yd[0]);
          return (
            <g key={f}>
              <line
                x1={x(xv)}
                x2={x(xv)}
                y1={top}
                y2={height - bottom}
                stroke="#eef1f7"
              />
              <line
                x1={left}
                x2={width - right}
                y1={y(yv)}
                y2={y(yv)}
                stroke="#e9edf5"
                strokeDasharray="3 5"
              />
              <text
                x={x(xv)}
                y={height - bottom + 20}
                textAnchor="middle"
                className="bench-axis"
              >
                {tick(xv)}
              </text>
              <text
                x={left - 10}
                y={y(yv) + 4}
                textAnchor="end"
                className="bench-axis"
              >
                {tick(yv)}
              </text>
            </g>
          );
        })}
        {mode === "parity" && (
          <line
            x1={x(xd[0])}
            y1={y(xd[0])}
            x2={x(xd[1])}
            y2={y(xd[1])}
            stroke="#aab3c7"
            strokeDasharray="5 5"
          />
        )}
        {mode === "residual" && (
          <line
            x1={left}
            x2={width - right}
            y1={y(0)}
            y2={y(0)}
            stroke="#a3afc7"
            strokeDasharray="5 5"
          />
        )}
        {points.map(({ point, training }) => (
          <circle
            key={`${training}-${point.row}`}
            cx={x(getX(point))}
            cy={y(getY(point))}
            r={width < 500 ? 3 : 3.6}
            fill={training ? "#31a39a" : "#7281dc"}
            fillOpacity={training ? 0.42 : 0.64}
            stroke="white"
            strokeWidth=".5"
            onMouseEnter={() => setActive({ point, training })}
            onClick={() => setActive({ point, training })}
          >
            <title>{`样本${point.row}：真实${number(point.actual)}，预测${number(point.prediction)}`}</title>
          </circle>
        ))}
        <text x={left} y="12" className="bench-axis-label">
          {yLabel}
        </text>
        <text
          x={width - right}
          y={height - 5}
          textAnchor="end"
          className="bench-axis-label"
        >
          {xLabel}
        </text>
      </svg>
      {active && (
        <div className="bench-chart-tooltip">
          <strong>
            {active.training ? "训练" : "验证"}样本 #{active.point.row}
          </strong>
          <span>真实 {number(active.point.actual)}</span>
          <span>预测 {number(active.point.prediction)}</span>
          <span>残差 {number(active.point.residual)}</span>
        </div>
      )}
      <div className="bench-legend">
        <span>
          <i className="dot" style={{ background: "#7281dc" }} />
          验证数据（{result.validation_predictions.length}点）
        </span>
        {showTraining && (
          <span>
            <i className="dot teal" />
            训练数据（最多200点）
          </span>
        )}
        <span>
          {mode === "parity"
            </span>
            <span className="topbar-separator" />
            <button className="text-button" onClick={() => setModal("guide")}>
              <BookOpen size={16} />
              使用指南
            </button>
            <span className="avatar small">研</span>
          </div>
        </header>

        <main className="content">
          {view === "datasets" && <DatasetLab onNotify={setToast} />}
          {view === "studio" && (
            <>
              <div className="page-heading">
                <div>
                  <div className="eyebrow">
                    <span>交互实验 {scene.number}</span>
                    <span className="eyebrow-sep">/</span>
                    <span>机器学习基础</span>
                  </div>
                  <h1>
                    {scene.title}
                    <span className="level-badge">基础探索</span>
                  </h1>
                  <p>{scene.description}</p>
                </div>
                <div className="heading-actions">
                  <button
                    className="button secondary"
                    disabled={!result || busy}
                    onClick={() => {
                      setTitle(`${scene.short} · ${params.degree}阶模型`);
                      setNote("");
                      setModal("save");
                    }}
                  >
                    <Save size={16} />
                    保存实验
                  </button>
                  <button
                    className="button primary"
                    disabled={!result || busy}
                    onClick={() => setModal("report")}
                  >
                    <ArrowDownToLine size={16} />
                    导出报告
                  </button>
                </div>
              </div>

              <div className="task-banner">
                <span className="task-icon">
                  <Target size={20} />
                </span>
                <div>
                  <strong>今天的探索任务</strong>
                  <span>{scene.task}</span>
                </div>
                <button
                  onClick={() =>
                    document
                      .getElementById("prediction")
                      ?.scrollIntoView({ behavior: "smooth", block: "center" })
                  }
                >
                  先做个预测
                  <ArrowRight size={15} />
                </button>
              </div>

              {error && (
                <div className="error-banner" role="alert">
                  <span>{error}</span>
                  <button onClick={() => setRetry((r) => r + 1)}>
                    重新连接
                  </button>
                </div>
              )}
              <div
                className={`metrics-grid ${busy ? "updating" : ""}`}
                aria-busy={busy}
              >
                <Metr…124 tokens truncated…"
                  tag="VALIDATION MSE"
                  value={result ? metric(result.metrics.validation_mse) : "—"}
                  color="coral"
                  caption="80 个样本 · 帮你选择参数"
                />
                <MetricCard
                  icon={<Layers3 size={16} />}
                  label="泛化差距"
                  tag="GENERALIZATION GAP"
                  value={result ? metric(result.metrics.gap) : "—"}
                  color="blue"
                  caption="验证误差 − 训练误差"
                />
                <div className="metric-card diagnosis-card">
                  <div className="metric-label">
                    <span>
                      <ShieldCheck size={16} />
                      当前诊断
                    </span>
                    <i
                      className={`status-dot ${result?.diagnosis.tone || ""}`}
                    />
                  </div>
                  <strong className="diagnosis-value">
                    {result?.diagnosis.label || "正在计算实验"}
                  </strong>
                  <p>
                    基于误差的教学提示
                    <span
                      className="metric-info"
                      title="规则诊断用于探索，不替代严格的统计检验。"
                    >
                      <CircleHelp size={13} />
                    </span>
                  </p>
                </div>
              </div>

              <div className="workspace-grid">
                <section className="panel chart-panel">
                  <div className="panel-heading">
                    <div>
                      <h2>
                        <span className="panel-dot" />
                        看见模型如何拟合
                      </h2>
                      <p>改变右侧参数，观察曲线与误差的变化</p>
                    </div>
                    <span className="live-badge">
                      {busy ? (
                        <LoaderCircle size={12} className="spin" />
                      ) : (
                        <span />
                      )}
                      {busy ? "更新中" : "实时计算"}
                    </span>
                  </div>
                  <div className="chart-toolbar">
                    <div className="segmented">
                      <button
                        className={chartTab === "fit" ? "chosen" : ""}
                        onClick={() => setChartTab("fit")}
                      >
                        <Activity size={14} />
                        拟合曲线
                      </button>
                      <button
                        className={chartTab === "sweep" ? "chosen" : ""}
                        onClick={() => {
                          setChartTab("sweep");
                          if (!sweep && !sweeping) void scan();
                        }}
                      >
                        <BarChart3 size={14} />
                        复杂度扫描
                      </button>
                    </div>
                    <span className="chart-hint">
                      {chartTab === "fit"
                        ? "悬停探索数据点"
                        : "同一数据 · 比较 1—15 阶"}
                    </span>
                  </div>
                  {chartTab === "fit" && (
                    <div className="experiment-presets">
                      <span>快速对照</span>
                      {[1, 4, 15].map((degree) => (
                        <button
                          key={degree}
                          className={params.degree === degree ? "selected" : ""}
                          onClick={() => update("degree", degree)}
                        >
                          {degree} 阶模型
                        </button>
                      ))}
                      <small>保持其他条件不变</small>
                    </div>
                  )}
                  {chartTab === "fit" ? (
                    <FitChart result={result} />
                  ) : (
                    <div className="sweep-container">
                      {sweep ? (
                        <>
                          <ErrorChart data={sweep} current={params.degree} />
                          <div className="sweep-summary">
                            <span>
                              验证误差最小：
                              <strong>{sweep.best_degree} 阶</strong>
                            </span>
                            <button
                              className="text-button"
                              onClick={() => {
                                update("degree", sweep.best_degree);
                                setChartTab("fit");
                              }}
                            >
                              应用此阶数
                              <ArrowRight size={14} />
                            </button>
                          </div>
                          <p className="muted small-copy">
                            纵轴采用对数尺度。橙线为验证误差，青线为训练误差。最小值只针对当前数据与正则强度。
                          </p>
                        </>
                      ) : (
                        <div className="empty-chart">
                          <LoaderCircle
                            size={28}
                            className={sweeping ? "spin" : ""}
                          />
                          <p>
                            {sweeping
                              ? "正在比较不同复杂度…"
                              : "运行扫描，找到当前数据的平衡点。"}
                          </p>
                          {!sweeping && (
                            <button
                              className="button secondary"
                              onClick={() => void scan()}
                            >
                              开始扫描
                            </button>
                          )}
                        </div>
                      )}
                    </div>
                  )}
                  <div className="chart-footer">
                    <span>
                      <ShieldCheck size={13} />
                      固定种子 {params.seed} · 独立数据划分
                    </span>
                    <span>
                      {result?.elapsed_ms ?? "—"} ms
                      <span className="subtle-dot">·</span>合成数据
                    </span>
                  </div>
                </section>

                <section className="panel parameters-panel">
                  <div className="panel-heading compact">
                    <h2>
                      <Settings2 size={17} />
                      实验参数
                    </h2>
                    <button
                      className="icon-button"
                      aria-label="重置当前实验参数"
                      title="重置参数"
                      onClick={() => setParams({ ...scene.defaults })}
                    >
                      <RotateCcw size={16} />
                    </button>
                  </div>
                  <div className="parameter-controls">
                    <Slider
                      label="模型复杂度"
                      tag="多项式阶数"
                      value={params.degree}
                      display={`${params.degree}`}
                      min={1}
                      max={15}
                      step={1}
                      onChange={(v) => update("degree", v)}
                      left="1 · 简单"
                      right="15 · 复杂"
                    />
                    <div className="degree-preview">
                      ŷ = w₀ + w₁x + ··· + w{params.degree}x
                      <sup>{params.degree}</sup>
                    </div>
                    <Slider
                      label="训练样本"
                      tag="数据量"
                      value={params.samples}
                      display={`${params.samples} 个`}
                      min={12}
                      max={160}
                      step={1}
                      onChange={(v) => update("samples", v)}
                      left="12"
                      right="160"
                    />
                    <Slider
                      label="噪声水平"
                      tag="标准差 σ"
                      value={params.noise}
                      display={params.noise.toFixed(2)}
                      min={0}
                      max={0.6}
                      step={0.01}
                      onChange={(v) => update("noise", v)}
                      left="0 · 无噪声"
                      right="0.60"
                    />
                    <Slider
                      label="正则化强度"
                      tag="Ridge α"
                      value={Math.max(0, alphaValues.indexOf(params.alpha))}
                      display={alphaLabel(params.alpha)}
                      min={0}
                      max={7}
                      step={1}
                      onChange={(v) => update("alpha", alphaValues[v])}
                      left="弱约束"
                      right="强约束"
                    />
                  </div>
                  <div className="seed-row">
                    <span>随机种子</span>
                    <input
                      aria-label="随机种子"
                      type="number"
                      min="0"
                      max="999999"
                      value={params.seed}
                      onChange={(e) =>
                        update(
                          "seed",
                          Math.max(
                            0,
                            Math.min(999999, Number(e.target.value) || 0),
                          ),
                        )
                      }
    setEvaluating(true);
    try {
      const value = await api<{
        test_rmse: number;
        test_r2: number;
        test_samples: number;
        note: string;
      }>("/bench/final", params, controller.signal);
      setFinalResult(value);
      const next = Array.from(new Set([...exposed, params.dataset]));
      setExposed(next);
      localStorage.setItem("fitlab-test-exposure", JSON.stringify(next));
    } catch (e) {
      if ((e as Error).name !== "AbortError") onNotify((e as Error).message);
    } finally {
      if (!controller.signal.aborted) setEvaluating(false);
    }
  }

  return (
    <div className="dataset-lab">
      <div className="page-heading">
        <div>
          <div className="eyebrow">
            <span>迁移实验</span>
            <span>/</span>
