function MetricCard({
  icon,
  label,
  tag,
  value,
  color,
  caption,
}: {
  icon: React.ReactNode;
  label: string;
  tag: string;
  value: string;
  color: string;
  caption: string;
}) {
  return (
    <div className={`metric-card ${color}`}>
      <div className="metric-label">
        <span>
          {icon}
          {label}
        </span>
        <small>{tag}</small>
      </div>
      <strong className="metric-value">{value}</strong>
      <p>{caption}</p>
    </div>
  );
}

