    if (!matched) return;
    setCheck({ key, gate });
    setHint("");
    setCopied(false);
  }
  function coordinates(e: PointerEvent<SVGGElement>) {
    const rect = e.currentTarget.ownerSVGElement!.getBoundingClientRect();
    return {
      x: Math.max(
