+  function position(){
+    const anchor=button.current!, tip=panel.current!, r=anchor.getBoundingClientRect(), box=tip.getBoundingClientRect();
+    tip.style.left=`${Math.max(16,Math.min(innerWidth-box.width-16,r.left+r.width/2-box.width/2))}px`;
+    tip.style.top=`${Math.max(16,r.bottom+10+box.height<=innerHeight-16?r.bottom+10:r.top-box.height-10)}px`;
+  }
+  function show(pin=false){clear();if(pin)pinned.current=true;dismissed.current=false;const tip=panel.current!;if(!tip.matches(":popover-open"))tip.showPopover();position();}
+  function hide(){clear();pinned.current=false;if(panel.current?.matches(":popover-open"))panel.current.hidePopover();}
