+  useEffect(()=>()=>clear(),[]);
+  useEffect(()=>{
+    if(!open)return;
+    let frame=0;
+    const update=()=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(position);};
+    const escape=(e:KeyboardEvent)=>{if(e.key==="Escape"){dismissed.current=true;hide();}};
+    window.addEventListener("resize",update);window.addEventListener("scroll",update,true);document.addEventListener("keydown",escape,true);
+    return()=>{cancelAnimationFrame(frame);window.removeEventListener("resize",update);window.removeEventListener("scroll",update,true);document.removeEventListener("keydown",escape,true);};
+  },[open]);
+  return <>
+    <button ref={button} type="button" className="help-hint-trigger" aria-label={title} aria-expanded={open} aria-controls={id} aria-describedby={open?id:undefined} popoverTarget={id}
+      onPointerDown={()=>{pointerDown.current=true;}}
+      onPointerEnter={e=>{if(e.pointerType!=="touch")show();}}
+      onPointerLeave={()=>queueClose()}
+      onFocus={()=>{if(!pointerDown.current&&!dismissed.current)show();}}
+      onBlur={()=>{pointerDown.current=false;dismissed.current=false;queueClose(true);}}
