        onToggle={(e) => {
          const showing = e.currentTarget.matches(":popover-open");
          setOpen(showing);
          if (!showing) {
            pinned.current = false;
            clear();
          }
        }}
      >
        <strong>{title}</strong>
        <div>{children}</div>
      </div>
    </>
  );
}
