          test_previously_viewed: previouslyViewed,
          learning_attempt_id: learningAttemptId,
        },
        controller.signal,
      );
      if (!controller.signal.aborted && currentKey.current === key)
        setPlan(value);
    } catch (e) {
      if ((e as Error).name !== "AbortError") setError((e as Error).message);
