    s = {'id':identity(raw['id']), 'created_at':stamp(raw['created_at']), 'updated_at':learning.now(), 'imported_at':learning.now(),
         'mode':raw['mode'] if raw.get('mode') in ('online','rules') else 'rules', 'model':str(raw.get('model') or '')[:100] o…2425 tokens truncated…"");
