+ indigo:{name:'星空靛',brand:'#5551a5',ink:'#2d2d48',muted:'#64637e',bg:'#f6f7fd',soft:'#e9e9f8',nav:'#2e2d50'},
+} as const;
+export type Palette=keyof typeof palettes;
