def test_builtin_cancel_and_student_upload_removed(client):
    c=client
    assert c.post('/lab/import',json={'csv':'x,y\n1,2'}).status_code==404
    assert c.post('/lab/import/inspect',json={'csv':'x,y\n1,2'}).status_code==404
