export function JourneySteps({ attempt }: { attempt: LearningAttempt | null }) {
  const phase = !attempt ? 0 : attempt.stage === "experiment" ? 1 : 2;
  const complete = attempt?.stage === "complete";
  const labels = ["先作预测", "动手实验", "迁移验证"];
  const notes = [
    attempt ? "判断已锁定" : "留下你的直觉",
